import random, collections
random.seed(7)
routes = [("reviews-v1", 90), ("reviews-v2", 10)]
def pick():
    r = random.uniform(0, 100); acc = 0
    for name, w in routes:
        acc += w
        if r < acc: return name
print(dict(collections.Counter(pick() for _ in range(10_000))))
# {'reviews-v1': 9004, 'reviews-v2': 996}
